import Foundation

enum CompanionHTML {
    static let page = #"""
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="dark"><title>LaunchDeck Companion</title>
<style>
:root{font-family:ui-sans-serif,system-ui,-apple-system,sans-serif;color:#ecf2ff;background:#10141e;font-size:15px}*{box-sizing:border-box}body{margin:0;padding:max(20px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) max(20px,env(safe-area-inset-bottom)) max(12px,env(safe-area-inset-left))}main{max-width:940px;margin:auto}header{display:flex;align-items:center;gap:12px;margin-bottom:24px}h1{font-size:20px;letter-spacing:-.6px;margin:0}header p{margin:3px 0 0;color:#a3afc7;font-size:12px}.status{margin-left:auto;font-size:12px;color:#a3afc7;display:flex;align-items:center;gap:6px}.dot{width:7px;height:7px;background:#fcac58;border-radius:50%}.online .dot{background:#6ce6b7}button,select,input{font:inherit;color:inherit}button,select{cursor:pointer}button:disabled,select:disabled{cursor:default;opacity:.45}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #9eaaff;outline-offset:2px}.panel{padding:24px;border:1px solid #30374a;border-radius:20px;background:#191f2c;max-width:440px;margin:50px auto}.panel h2{margin:0 0 8px}.panel p{color:#a3afc7;line-height:1.5;margin-bottom:22px}label{display:block;font-size:12px;color:#a3afc7;margin:18px 0 8px}input,select{border:1px solid #394257;border-radius:10px;background:#141a26;padding:12px;width:100%}input.code{font-size:24px;letter-spacing:5px}button.primary{border:0;background:#dce5ff;color:#17223c;padding:12px 18px;border-radius:10px;width:100%;font-weight:650;margin-top:22px}.toolbar{display:flex;align-items:center;gap:16px;margin-bottom:16px}.context{flex:1;min-width:0}.context h2{font-size:20px;margin:0 0 3px}.context p{font-size:12px;color:#a3afc7;margin:0}.toolbar select{width:190px;font-size:13px;padding:10px}.deck{display:grid;gap:clamp(4px,1vw,12px);width:100%;touch-action:manipulation}.pad{position:relative;min-width:0;aspect-ratio:1;border-radius:clamp(6px,1.4vw,16px);border:1px solid color-mix(in srgb,var(--color) 65%,#667085);background:linear-gradient(145deg,color-mix(in srgb,var(--color) 28%,#202635),color-mix(in srgb,var(--color) 9%,#161c28));box-shadow:inset 0 1px 0 #ffffff12;padding:5px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:4px;overflow:hidden;transition:transform .08s,border-color .08s}.pad:active,.pad.pressed{transform:scale(.95);border-color:#fff}.pad .symbol{font-size:clamp(14px,2.5vw,26px);line-height:1.15}.pad img{width:43%;height:43%;object-fit:contain}.pad .label{font-size:clamp(8px,1.55vw,13px);line-height:1.2;font-weight:650;max-width:100%;overflow-wrap:anywhere;text-align:center}.pad .action{font-size:10px;color:#a3afc7;display:none}.pad .feedback{position:absolute;right:4px;top:3px;font-size:10px;color:#fff}.feedback-line{min-height:38px;margin:16px 0 0;color:#b7c7e5;font-size:13px;line-height:1.4}.error{color:#ffb0ac}.footer{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#7f8ba3;margin-top:16px}.text-button{background:none;border:0;color:#a3afc7;padding:10px;font-size:12px}.offline{opacity:.55}body[data-busy=true] .pad{cursor:wait}@media(min-width:700px){.pad .action{display:block;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pad{padding:8px}}@media(max-width:420px){.toolbar{gap:10px}.toolbar select{width:125px}.context h2{font-size:17px}header{margin-bottom:20px}.panel{padding:20px}}
@media(min-width:700px) and (min-height:600px) and (orientation:landscape){main{max-width:min(940px,calc(100svh - 250px))}.pad{padding:4px;gap:3px}.pad .symbol{font-size:18px}.pad .label{font-size:11px}.pad .action{display:none}}
.advanced{margin-top:12px;color:#a3afc7;font-size:13px}.advanced summary{cursor:pointer;padding:8px 0}.advanced label{display:block;margin:8px 0}.advanced select{max-width:100%;padding:8px}.advanced p{line-height:1.4}.advanced button{margin-left:8px}
</style></head><body><main>
<header><div><h1>LaunchDeck</h1><p>Companion · your Mac’s live deck</p></div><div class="status" id="status"><span class="dot"></span><span id="connection">Disconnected</span></div></header>
<section class="panel" id="pair"><h2>Connect to your Mac</h2><p>Open Companion in LaunchDeck on your Mac, then enter its pairing code. Both devices need to be on the same trusted network.</p><form id="pair-form"><label for="name">Browser name</label><input id="name" maxlength="80" autocomplete="nickname" value="My browser"><label for="code">Pairing code</label><input class="code" id="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required placeholder="00000000"><button class="primary" id="pair-button">Pair browser</button><p class="error" id="pair-error" role="alert"></p></form></section>
<section id="runtime" hidden><div class="toolbar"><div class="context"><h2 id="profile-name"></h2><p id="page-name"></p></div></div><div id="deck" class="deck offline" aria-label="Deck controls"></div><p id="feedback" class="feedback-line" role="status" aria-live="polite"></p><details class="advanced"><summary>Advanced</summary><label for="profiles">Profile Override</label><p>Temporarily use a profile until automatic switching is resumed or LaunchDeck restarts.</p><select id="profiles" aria-label="Profile Override" disabled></select><button class="text-button" id="resume-auto" disabled>Resume Automatic Switching</button></details><div class="footer"><span id="model"></span><button class="text-button" id="forget">Forget this browser</button></div></section>
</main><script>
'use strict';
const $=id=>document.getElementById(id);
let token='',snapshot=null,online=false,busy=false,signature='',structure='',stopped=false;
let pollTimer=null,polling=false,refreshPending=false,burstUntil=0,sessionGeneration=0,snapshotController=null;
try{token=localStorage.getItem('launchdeck.companion.token')||''}catch{}
const artwork=new Map();
const symbols={'arrow.left':'←','arrow.right':'→','arrow.up':'↑','arrow.down':'↓','chevron.left':'‹','chevron.right':'›','folder':'▣','folder.fill':'▣','house':'⌂','house.fill':'⌂','play.fill':'▶','pause.fill':'Ⅱ','stop.fill':'■','keyboard':'⌨','command':'⌘','globe':'◎','link':'↗','doc':'▤','doc.fill':'▤','music.note':'♪','speaker.wave.2.fill':'♫','gearshape':'⚙','bolt.fill':'ϟ','star':'☆','star.fill':'★','checkmark':'✓','plus':'＋','minus':'−','return':'↵','text.cursor':'I','terminal':'›_'};
function store(){try{token?localStorage.setItem('launchdeck.companion.token',token):localStorage.removeItem('launchdeck.companion.token')}catch{}}
function state(connected,message){online=connected;$('connection').textContent=message;$('status').classList.toggle('online',connected);$('deck').classList.toggle('offline',!connected);$('profiles').disabled=!connected||busy;$('resume-auto').disabled=!connected||busy||snapshot?.mode!=='Manual';for(const button of $('deck').children)button.disabled=!connected||busy||button.dataset.enabled==='false'}
function clearArtwork(){for(const url of artwork.values())URL.revokeObjectURL(url);artwork.clear()}
function forget(message=''){sessionGeneration++;snapshotController?.abort();token='';store();snapshot=null;signature='';structure='';burstUntil=0;clearArtwork();$('runtime').hidden=true;$('pair').hidden=false;$('pair-error').textContent=message;state(false,'Unpaired')}
async function api(path,body,signal){const issuedToken=token,generation=sessionGeneration;const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:token?{'Authorization':'Bearer '+token}:{},body:body===undefined?undefined:JSON.stringify(body),signal:signal?AbortSignal.any([signal,AbortSignal.timeout(4000)]):AbortSignal.timeout(4000),cache:'no-store'});if(response.status===401&&path!=='pair'&&issuedToken===token&&generation===sessionGeneration){forget('This session expired or was revoked. Pair again on your Mac.');throw Error('Pairing required')}if(!response.ok){let message='Request failed';try{message=(await response.json()).error||message}catch{}throw Error(message)}return response}
async function loadArtwork(id,image,revision){if(artwork.has(id)){image.src=artwork.get(id);return}try{const response=await api('artwork/'+encodeURIComponent(id));const blob=await response.blob();if(!snapshot||!image.isConnected||!snapshot.controls.some(control=>control.artworkID===id))return;let url=artwork.get(id);if(!url){url=URL.createObjectURL(blob);artwork.set(id,url)}image.src=url}catch{image.remove()}}
function rebuild(data){snapshot=data;$('pair').hidden=true;$('runtime').hidden=false;$('profile-name').textContent=data.profileName;$('page-name').textContent=(data.mode==='Manual'?'Temporary override':'Automatic')+' · '+data.pageName;$('model').textContent=data.model+' · synced with desktop';$('feedback').textContent=data.feedback||'';const select=$('profiles');select.replaceChildren();let option=document.createElement('option');option.value='';option.textContent='Automatic switching';select.append(option);for(const profile of data.profiles){option=document.createElement('option');option.value=profile.id;option.textContent=profile.name;select.append(option)}select.value=data.mode.toLowerCase().includes('auto')?'':(data.profileID||'');const deck=$('deck');deck.style.gridTemplateColumns='repeat('+Math.min(16,Math.max(1,data.columns))+',minmax(0,1fr))';deck.replaceChildren();const usedArtwork=new Set();for(const control of data.controls){const button=document.createElement('button');button.className='pad';button.type='button';button.style.setProperty('--color',/^#[0-9a-f]{6}$/i.test(control.color)?control.color:'#7487a7');button.style.gridRow=String(control.row+1);button.style.gridColumn=String(control.column+1);button.dataset.enabled=String(control.enabled);button.disabled=!online||busy||!control.enabled;button.title=control.label+' · '+control.action;button.setAttribute('aria-label',control.label+', '+control.action);if(control.artworkID){const image=document.createElement('img');image.alt='';button.append(image);usedArtwork.add(control.artworkID);loadArtwork(control.artworkID,image,data.revision)}else if(control.symbolName){const symbol=document.createElement('span');symbol.className='symbol';symbol.textContent=symbols[control.symbolName]||'◇';symbol.setAttribute('aria-hidden','true');button.append(symbol)}const label=document.createElement('span');label.className='label';label.textContent=control.label||'·';button.append(label);const action=document.createElement('span');action.className='action';action.textContent=control.action;button.append(action);const feedback=document.createElement('span');feedback.className='feedback';feedback.textContent=control.feedback||'';button.append(feedback);button.addEventListener('click',()=>press(control.index,button));deck.append(button)}for(const [id,url]of artwork)if(!usedArtwork.has(id)){URL.revokeObjectURL(url);artwork.delete(id)}}
// Animation frames change presentation values without replacing focused controls.
function render(data){const nextStructure=JSON.stringify([data.profileID,data.profileName,data.mode,data.pageID,data.pageName,data.model,data.rows,data.columns,data.profiles,data.controls.map(control=>[control.index,control.row,control.column,control.label,control.action,control.symbolName,control.artworkID,control.enabled])]);snapshot=data;if(nextStructure!==structure){structure=nextStructure;rebuild(data);return}$('feedback').textContent=data.feedback||'';for(let i=0;i<data.controls.length;i++){const control=data.controls[i],button=$('deck').children[i];button.style.setProperty('--color',/^#[0-9a-f]{6}$/i.test(control.color)?control.color:'#7487a7');button.querySelector('.feedback').textContent=control.feedback||''}}
function pollDelay(){return document.hidden?4000:(online&&(snapshot?.animated||Date.now()<burstUntil)?67:800)}
function schedulePoll(delay=pollDelay()){if(pollTimer!==null)clearTimeout(pollTimer);pollTimer=null;if(!stopped)pollTimer=setTimeout(()=>{pollTimer=null;poll()},delay)}
function refresh(){if(stopped)return;if(pollTimer!==null)clearTimeout(pollTimer);pollTimer=null;if(polling||busy){refreshPending=true;return}if(document.hidden){schedulePoll();return}poll()}
async function poll(){if(stopped)return;if(polling||busy){refreshPending=true;return}if(!token){schedulePoll();return}polling=true;refreshPending=false;const generation=sessionGeneration,controller=new AbortController();snapshotController=controller;try{const response=await api('snapshot',undefined,controller.signal);const data=await response.json();if(stopped||generation!==sessionGeneration||!token)return;state(true,'Connected');const next=JSON.stringify(data);if(next!==signature){signature=next;render(data)}state(true,'Connected')}catch(error){if(!stopped&&generation===sessionGeneration&&token){state(false,'Reconnecting…');$('feedback').textContent='Disconnected. Controls resume after synchronization.'}}finally{polling=false;if(snapshotController===controller)snapshotController=null;if(!stopped){if(refreshPending&&!busy){refreshPending=false;refresh()}else if(!busy)schedulePoll()}}}
async function press(index,button){if(!online||busy||!snapshot)return;const displayed=snapshot,generation=sessionGeneration;busy=true;state(true,'Connected');button.classList.add('pressed');try{await api('press',{index,revision:displayed.revision,pageID:displayed.pageID});if(generation===sessionGeneration&&token){$('feedback').textContent='Sent to your Mac.';burstUntil=Date.now()+4000;signature=''}}catch(error){if(generation===sessionGeneration&&token){$('feedback').textContent=error.message;signature='';if(error.name==='TypeError'||error.name==='TimeoutError')state(false,'Reconnecting…')}}finally{button.classList.remove('pressed');busy=false;state(online,online?'Connected':'Reconnecting…');refresh()}}
async function setProfileOverride(profileID){if(!online||busy)return;const generation=sessionGeneration;busy=true;state(true,'Connected');try{await api('activate',{profileID});if(generation===sessionGeneration)signature=''}catch(error){if(generation===sessionGeneration&&token){$('feedback').textContent=error.message;signature=''}}finally{busy=false;state(online,online?'Connected':'Reconnecting…');refresh()}}
$('profiles').addEventListener('change',()=>setProfileOverride($('profiles').value||null));
$('resume-auto').addEventListener('click',()=>{if(snapshot?.mode==='Manual')return setProfileOverride(null)});
$('pair-form').addEventListener('submit',async event=>{event.preventDefault();const generation=sessionGeneration;$('pair-button').disabled=true;$('pair-error').textContent='';try{const response=await api('pair',{code:$('code').value,name:$('name').value});const data=await response.json();if(generation!==sessionGeneration||stopped)return;sessionGeneration++;token=data.token;store();signature='';$('code').value='';$('pair').hidden=true;$('runtime').hidden=false;state(false,'Synchronizing…');refresh()}catch(error){if(generation===sessionGeneration)$('pair-error').textContent=error.message}finally{$('pair-button').disabled=false}});
$('forget').addEventListener('click',()=>forget());window.addEventListener('offline',()=>state(false,'Disconnected'));document.addEventListener('visibilitychange',()=>{if(document.hidden)schedulePoll();else refresh()});window.addEventListener('pagehide',()=>{stopped=true;if(pollTimer!==null)clearTimeout(pollTimer);pollTimer=null;snapshotController?.abort();clearArtwork()});window.addEventListener('pageshow',()=>{if(stopped){stopped=false;signature='';structure='';refresh()}});if(token){$('pair').hidden=true;$('runtime').hidden=false;state(false,'Synchronizing…')}poll();
</script></body></html>
"""#
}
